const message = String($json.execution?.error?.message ?? $json.error?.message ?? 'UNCLASSIFIED_ERROR');
let status = 'manual_handoff';
let retry = false;
if (/SCHEMA_|missing|required|invalid json/iu.test(message)) status = 'needs_input';
else if (/401|403|permission|forbidden/iu.test(message)) status = 'failed_permanent';
else if (/429|503|5\d\d|timeout|ECONN/iu.test(message)) { status = 'retryable_failed'; retry = true; }
else if (/ACTION_STATUS_UNKNOWN/iu.test(message)) status = 'action_status_unknown';
return [{ json: {
  workflow_id: $json.workflow?.id ?? null,
  execution_id: $json.execution?.id ?? null,
  failed_node: $json.execution?.lastNodeExecuted ?? null,
  task_id: $json.execution?.customData?.task_id ?? null,
  run_id: $json.execution?.customData?.run_id ?? null,
  error_summary: message.slice(0, 300),
  status,
  retry_allowed: retry,
  retry_limit: retry ? 2 : 0,
  retry_total_limit_seconds: retry ? 300 : 0,
  recorded_at: $now.toISO()
} }];
